```yaml
schema: 13
scope: global
id: global:safe_worktree_gc
name: Safe Worktree Cleanup (7d)
on:
  schedule:
    - cron: "0 3 * * *"
      timezone: Local
      overlap: skip
env:
  RETENTION_DAYS: "7"
  DRY_RUN: "true"
  REPORT_PROJECT_ID: ${{ vars.GC_REPORT_PROJECT_ID }}
  EXTRA_REPOS: ""
steps:
  - id: gc
    timeout_minutes: 30
    run: |
      python3 - <<'PY'
      import datetime, json, os, subprocess, time
      from pathlib import Path

      CANBAN = os.environ.get("CANBAN_CLI") or "canban"
      DAYS = int(os.environ.get("RETENTION_DAYS", "7"))
      DRY_RUN = os.environ.get("DRY_RUN", "false").lower() in ("1", "true", "yes")
      REPORT_PID = os.environ.get("REPORT_PROJECT_ID", "").strip()
      EXTRA = [p.strip() for p in os.environ.get("EXTRA_REPOS", "").split(":") if p.strip()]
      CUTOFF = time.time() - DAYS * 86400
      CWD = Path.cwd().resolve()
      GIT_OPS = ("MERGE_HEAD", "CHERRY_PICK_HEAD", "REVERT_HEAD", "rebase-merge", "rebase-apply", "BISECT_LOG")

      def run(cmd, cwd=None):
          return subprocess.run(cmd, cwd=cwd, capture_output=True, text=True)

      def rpc(method, params):
          r = run([CANBAN, "call", method, json.dumps(params)])
          return json.loads(r.stdout) if r.returncode == 0 and r.stdout.strip() else None

      def dir_bytes(path: Path) -> int:
          if not path.exists():
              return 0
          r = run(["du", "-sk", str(path)])
          if r.returncode == 0 and r.stdout.strip():
              return int(r.stdout.split()[0]) * 1024
          return 0

      def fmt_bytes(b: int) -> str:
          if b >= 1024 ** 3:
              return f"{b / (1024 ** 3):.2f} GB"
          if b >= 1024 ** 2:
              return f"{b / (1024 ** 2):.1f} MB"
          return f"{b // 1024} KB" if b >= 1024 else f"{b} B"

      def safe(s: str) -> str:
          return (s or "").replace("`", "'").replace("\n", " ").replace("@", "@\u200b").strip()

      def default_ref(repo: Path):
          r = run(["git", "-C", str(repo), "symbolic-ref", "-q", "refs/remotes/origin/HEAD"])
          if r.returncode == 0 and r.stdout.strip():
              return r.stdout.strip()
          for ref in ("refs/heads/main", "refs/heads/master", "refs/remotes/origin/main", "refs/remotes/origin/master"):
              if run(["git", "-C", str(repo), "rev-parse", "--verify", "-q", ref]).returncode == 0:
                  return ref
          return None

      projects = rpc("project.list", {}) or []
      proj_by_id = {p["id"]: p for p in projects}
      repos = {Path(p["directory"]).resolve(): p["name"] for p in projects if Path(p["directory"]).exists()}
      for extra in EXTRA:
          ep = Path(extra).expanduser().resolve()
          if ep.exists() and ep not in repos:
              repos[ep] = ep.name

      if not REPORT_PID and projects:
          REPORT_PID = projects[0]["id"]

      cleaned, failed, skipped, seen = [], [], [], set()
      stats = {name: {"cleaned": 0, "bytes": 0, "failed": 0, "skipped": 0} for name in set(repos.values())}
      def bump(repo_name, key, delta=1): stats.setdefault(repo_name, {"cleaned": 0, "bytes": 0, "failed": 0, "skipped": 0})[key] += delta

      # 階段 1：先呼叫 Canban 原生 worktree gc（清理託管 worktree 並同步 SQLite 紀錄）
      dry_gc = run([CANBAN, "worktree", "gc", "--merged-before", f"{DAYS}d", "--dry-run"])
      dry_data = json.loads(dry_gc.stdout) if dry_gc.returncode == 0 and dry_gc.stdout.strip() else {}
      pre_sizes = {}
      for bucket in ("removed", "dirty", "skipped"):
          for item in dry_data.get(bucket, []):
              raw_p = item.get("path") or ""
              if not raw_p:
                  continue
              p = Path(raw_p).resolve()
              seen.add(p)
              if bucket == "removed" and not item.get("missing"):
                  pre_sizes[str(p)] = dir_bytes(p)

      gc_data = dry_data
      if not DRY_RUN:
          real_gc = run([CANBAN, "worktree", "gc", "--merged-before", f"{DAYS}d"])
          if real_gc.returncode == 0 and real_gc.stdout.strip():
              gc_data = json.loads(real_gc.stdout)

      for item in gc_data.get("removed", []):
          rname = item.get("project_name") or proj_by_id.get(item.get("project_id", ""), {}).get("name", "canban")
          sz = pre_sizes.get(str(Path(item.get("path", "")).resolve()), 0)
          cleaned.append({"repo": rname, "path": item.get("path", ""), "branch": item.get("branch", ""), "bytes": sz, "note": "canban gc"})
          bump(rname, "cleaned"); bump(rname, "bytes", sz)
      for item in gc_data.get("dirty", []):
          rname = item.get("project_name") or proj_by_id.get(item.get("project_id", ""), {}).get("name", "canban")
          reason = item.get("reason", "")
          if reason in ("uncommitted_changes", "live_terminal_open"):
              skipped.append({"repo": rname, "path": item.get("path", ""), "cat": "dirty", "reason": reason})
              bump(rname, "skipped")
          else:
              failed.append({"repo": rname, "path": item.get("path", ""), "branch": item.get("branch", ""), "bytes": dir_bytes(Path(item.get("path", ""))), "reason": reason})
              bump(rname, "failed")
      for item in gc_data.get("skipped", []):
          rname = proj_by_id.get(item.get("project_id", ""), {}).get("name", "canban")
          skipped.append({"repo": rname, "path": item.get("path", ""), "cat": "recent", "reason": item.get("reason", "within_retention")})
          bump(rname, "skipped")

      # 階段 2：純 Git 掃描剩餘 / 外部 worktree（依提交時間 + HEAD mtime 過濾 7d，無需 snapshot）
      for repo, rname in repos.items():
          base_ref = default_ref(repo)
          wt_out = subprocess.run(["git", "-C", str(repo), "worktree", "list", "--porcelain", "-z"], capture_output=True)
          if wt_out.returncode != 0:
              continue
          entries, cur = [], {}
          for tok in wt_out.stdout.decode("utf-8", "replace").split("\0"):
              if not tok:
                  if cur: entries.append(cur); cur = {}
              elif " " in tok:
                  k, v = tok.split(" ", 1); cur[k] = v
              else:
                  cur[tok] = True
          prune_needed = False
          for idx, ent in enumerate(entries):
              raw_wt = ent.get("worktree", "")
              if not raw_wt:
                  continue
              wt = Path(raw_wt).resolve()
              if idx == 0 or wt == repo or wt == CWD or wt.name == "_merge_queue" or wt in seen:
                  continue
              if any(ent.get(flag) for flag in ("bare", "locked", "prunable")):
                  skipped.append({"repo": rname, "path": str(wt), "cat": "protected", "reason": "locked/bare/prunable"}); bump(rname, "skipped"); continue
              if not wt.exists():
                  prune_needed = True; continue
              if not base_ref:
                  skipped.append({"repo": rname, "path": str(wt), "cat": "unmerged", "reason": "no default branch"}); bump(rname, "skipped"); continue
              gd_raw = ent.get("gitdir") or run(["git", "-C", str(wt), "rev-parse", "--git-dir"]).stdout.strip()
              gd = Path(gd_raw) if gd_raw else wt / ".git"
              if not gd.is_absolute(): gd = (wt / gd).resolve()
              if any((gd / marker).exists() for marker in GIT_OPS):
                  skipped.append({"repo": rname, "path": str(wt), "cat": "dirty", "reason": "Git 操作進行中"}); bump(rname, "skipped"); continue
              st = run(["git", "-C", str(wt), "status", "--porcelain", "--untracked-files=all", "--ignore-submodules=none"])
              if st.returncode != 0 or st.stdout.strip():
                  skipped.append({"repo": rname, "path": str(wt), "cat": "dirty", "reason": "存在未提交修改"}); bump(rname, "skipped"); continue
              ct_res = run(["git", "-C", str(wt), "log", "-1", "--format=%ct", "HEAD"])
              commit_ts = int(ct_res.stdout.strip()) if ct_res.returncode == 0 and ct_res.stdout.strip().isdigit() else int(time.time())
              head_file = gd / "HEAD" if (gd / "HEAD").exists() else wt
              head_mtime = head_file.stat().st_mtime
              if max(commit_ts, head_mtime) > CUTOFF:
                  skipped.append({"repo": rname, "path": str(wt), "cat": "recent", "reason": f"{DAYS} 天內有活動"}); bump(rname, "skipped"); continue
              anc = run(["git", "-C", str(repo), "merge-base", "--is-ancestor", ent.get("HEAD", "HEAD"), base_ref])
              if anc.returncode != 0:
                  skipped.append({"repo": rname, "path": str(wt), "cat": "unmerged", "reason": f"尚未合入 {base_ref}"}); bump(rname, "skipped"); continue
              sz = dir_bytes(wt)
              branch = str(ent.get("branch", "")).removeprefix("refs/heads/") or "detached"
              age_d = int((time.time() - max(commit_ts, head_mtime)) // 86400)
              if DRY_RUN:
                  cleaned.append({"repo": rname, "path": str(wt), "branch": branch, "bytes": sz, "note": f"最後活動 {age_d} 天前"})
                  bump(rname, "cleaned"); bump(rname, "bytes", sz)
              else:
                  rm = run(["git", "-C", str(repo), "worktree", "remove", raw_wt])
                  if rm.returncode == 0:
                      cleaned.append({"repo": rname, "path": str(wt), "branch": branch, "bytes": sz, "note": f"最後活動 {age_d} 天前"})
                      bump(rname, "cleaned"); bump(rname, "bytes", sz); prune_needed = True
                  else:
                      failed.append({"repo": rname, "path": str(wt), "branch": branch, "bytes": sz, "reason": rm.stderr.strip() or rm.stdout.strip()})
                      bump(rname, "failed")
          if not DRY_RUN and prune_needed:
              run(["git", "-C", str(repo), "worktree", "prune"])

      # 階段 3：0 清理且 0 失敗則靜默退出，否則建立彙總 Card
      if not cleaned and not failed:
          print(f"Worktree 清理檢查完成：釋放 0 B，安全跳過 {len(skipped)} 個。")
          raise SystemExit(0)

      total_bytes = sum(x["bytes"] for x in cleaned)
      today = datetime.datetime.now().strftime("%Y-%m-%d")
      now_str = datetime.datetime.now().strftime("%Y-%m-%d %H:%M")
      prefix = "[Dry-Run] " if DRY_RUN else ("⚠️ " if failed else "")
      title = f"{prefix}Worktree 清理報告 ({today}) — 回收 {fmt_bytes(total_bytes)} ({len(cleaned)} 個)"
      if failed: title += f"，{len(failed)} 個失敗"

      lines = [
          "## 彙總", "",
          f"- **執行時間**: {now_str} · **模式**: {'演練預覽 (Dry-Run)' if DRY_RUN else '正式清理'}（閾值 `{DAYS}d`）",
          f"- **掃描範圍**: {len(repos)} 個儲存庫 · **已清理**: {len(cleaned)} 個 worktree · **釋放空間**: **{fmt_bytes(total_bytes)}**",
          f"- **清理失敗**: {len(failed)} 個 · **安全跳過**: {len(skipped)} 個", "",
          "## 按儲存庫統計", "",
          "| 儲存庫 | 已清理 | 釋放空間 | 清理失敗 | 安全跳過 |", "| --- | ---: | ---: | ---: | ---: |",
      ]
      for rname, st in sorted(stats.items()):
          lines.append(f"| `{safe(rname)}` | {st['cleaned']} | {fmt_bytes(st['bytes'])} | {st['failed']} | {st['skipped']} |")
      if failed:
          lines += ["", "## 清理失敗（需人工排查）", "", "| 儲存庫 | Worktree / 分支 | 佔用空間 | 失敗原因 |", "| --- | --- | ---: | --- |"]
          for f in failed:
              lines.append(f"| `{safe(f['repo'])}` | `{safe(f['path'])}` (`{safe(f['branch'])}`) | {fmt_bytes(f['bytes'])} | {safe(f['reason'])} |")
      if cleaned:
          lines += ["", f"## 已清理明細 ({len(cleaned)})", ""]
          for c in cleaned[:40]:
              lines.append(f"- `{safe(c['repo'])}` · `{safe(c['path'])}` (`{safe(c['branch'])}`) — {fmt_bytes(c['bytes'])}（{safe(c['note'])}）")
          if len(cleaned) > 40: lines.append(f"- ... 其餘 {len(cleaned) - 40} 個")
      if skipped:
          cats = {"dirty": "髒工作區 / 進行中操作", "unmerged": "尚未合併", "recent": f"{DAYS} 天內活躍", "protected": "鎖定 / 受保護目錄"}
          lines += ["", "## 安全跳過摘要（未刪除）", ""]
          for key, label in cats.items():
              grp = [s for s in skipped if s["cat"] == key]
              if grp:
                  sample = ", ".join(f"`{safe(Path(s['path']).name)}`" for s in grp[:8])
                  lines.append(f"- **{label}（{len(grp)}）**：{sample}{' ...' if len(grp) > 8 else ''}")

      body = "\n".join(lines)
      print(body)
      if REPORT_PID:
          card = rpc("card.create", {"project_id": REPORT_PID, "title": title, "body": body, "view": "full"})
          if not card:
              raise SystemExit("Failed to create report Card; verify REPORT_PROJECT_ID")
          if card and not DRY_RUN and not failed and "number" in card:
              run([CANBAN, "card", "resolve", "--project", REPORT_PID, "--card", str(card["number"]),
                   "--message", f"已回收 {fmt_bytes(total_bytes)}（{len(cleaned)} 個 worktree）"])
      PY
  - id: finish
    uses: complete
```

